mapper.select:
SELECT id, pmn, level, name, part_number, product_part_number, product_version, product_type, product_num, unit, remark, tag_number, subcategory, drawing_number, category, small_subcategory FROM efvs_product_bom WHERE deleted = 0 AND tenant_id = #{tenantId} AND product_part_number = #{productPartNumber}
AND name LIKE CONCAT('%', #{name}, '%')
AND part_number = #{partNumber}
AND product_version = #{productVersion}
AND product_type = #{productType}
ORDER BY id ASC
